import{_ as a,o as r,c as e,a2 as o}from"./chunks/framework.BQq6mqvm.js";const g=JSON.parse('{"title":"文件与回收站","description":"","frontmatter":{},"headers":[],"relativePath":"admin/files.md","filePath":"admin/files.md","lastUpdated":1790385461000}'),l={name:"admin/files.md"};function s(i,t,n,d,h,p){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="文件与回收站" tabindex="-1">文件与回收站 <a class="header-anchor" href="#文件与回收站" aria-label="Permalink to &quot;文件与回收站&quot;">​</a></h1><p>在左侧菜单进入<strong>管理 → 文件与回收站</strong>。这里可以看到<strong>全部文件（含已删除的）</strong>，并执行恢复或彻底删除。</p><h2 id="三种视图" tabindex="-1">三种视图 <a class="header-anchor" href="#三种视图" aria-label="Permalink to &quot;三种视图&quot;">​</a></h2><p>页面右上角可以切换：</p><table tabindex="0"><thead><tr><th>视图</th><th>内容</th></tr></thead><tbody><tr><td>有效文件</td><td>当前所有人正在使用的文件</td></tr><tr><td>回收站</td><td>已删除、等待彻底清理的文件</td></tr><tr><td>全部</td><td>两者都显示</td></tr></tbody></table><p>还可以按<strong>用户</strong>筛选，只看某位成员的文件。</p><h2 id="恢复文件" tabindex="-1">恢复文件 <a class="header-anchor" href="#恢复文件" aria-label="Permalink to &quot;恢复文件&quot;">​</a></h2><p>在<strong>回收站</strong>视图中找到文件，点击<strong>恢复</strong>。</p><p>恢复后：</p><ul><li>文件重新变为有效，所有人可以正常浏览和下载。</li><li><strong>到期时间重新计算</strong>，从恢复时刻起按「文件保留天数」重新计时。</li></ul><div class="tip custom-block"><p class="custom-block-title">什么时候需要恢复</p><p>用户误删了文件，或者文件到期自动清理了但还需要用，都可以在这里恢复。前提是还在<strong>回收站保留期内</strong>（默认 7 天）。</p></div><h2 id="彻底删除" tabindex="-1">彻底删除 <a class="header-anchor" href="#彻底删除" aria-label="Permalink to &quot;彻底删除&quot;">​</a></h2><p>点击<strong>彻底删除</strong>并确认后，文件会<strong>立即从磁盘和数据库中删除，不可恢复</strong>。</p><div class="danger custom-block"><p class="custom-block-title">不可恢复</p><p>彻底删除会同时删掉磁盘上的文件和数据库记录。确定不再需要时才执行。</p></div><h2 id="普通用户看不到回收站" tabindex="-1">普通用户看不到回收站 <a class="header-anchor" href="#普通用户看不到回收站" aria-label="Permalink to &quot;普通用户看不到回收站&quot;">​</a></h2><p>文件一旦进入回收站，<strong>连上传者本人都看不到</strong>，只有管理员能在这里看到并操作。</p><p>这是有意设计的：用户删除文件后界面立即清爽，同时又给了管理员一个挽回的窗口。</p><h2 id="关于到期时间列" tabindex="-1">关于到期时间列 <a class="header-anchor" href="#关于到期时间列" aria-label="Permalink to &quot;关于到期时间列&quot;">​</a></h2><p>列表中的「到期时间」显示该文件还有多少天会被自动清理，临近到期时会以红色标签提示。</p><p>「删除时间」与「彻底删除时间」两列只对回收站中的文件有意义。</p><h2 id="处理磁盘空间不足" tabindex="-1">处理磁盘空间不足 <a class="header-anchor" href="#处理磁盘空间不足" aria-label="Permalink to &quot;处理磁盘空间不足&quot;">​</a></h2><p>如果服务器磁盘快满了，按这个顺序处理：</p><ol><li>到<strong>工作台</strong>看回收站占用了多少空间。</li><li>到<strong>回收站</strong>视图，确认不需要的文件后点击<strong>彻底删除</strong>。</li><li>收窄「回收站保留天数」可以加快自动清理速度。</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="./workbench">工作台</a></li><li><a href="./settings">系统管理</a></li></ul>',25)])])}const u=a(l,[["render",s]]);export{g as __pageData,u as default};
